let TotalActiveUsers = toscalar(union pageViews, customEvents | where timestamp {TimeRange} | summarize dcount(user_Id));
let NewUsers = toscalar(
    union pageViews, customEvents
    | where timestamp > ago(400d)
    | summarize FirstSeen = min(timestamp) by user_Id
    | where FirstSeen {TimeRange}
    | count
);
let Current30d = toscalar(union pageViews, customEvents | where timestamp > ago(30d) | summarize dcount(user_Id));
let Previous30d = toscalar(union pageViews, customEvents | where timestamp between (ago(60d) .. ago(30d)) | summarize dcount(user_Id));
let MoMGrowthPercent = round(iif(Previous30d > 0, 100.0 * (Current30d - Previous30d) / Previous30d, 0.0), 1);
union
    (print Metric = "Active Users (selected period)", Value = toreal(TotalActiveUsers)),
    (print Metric = "New Users (selected period)", Value = toreal(NewUsers)),
    (print Metric = "MoM Growth % (rolling 30d)", Value = MoMGrowthPercent)

let CaseDetailUsers = toscalar(pageViews | where timestamp {TimeRange} | where url contains "/case-detail/" | summarize dcount(user_Id));
let NotesUsers = toscalar(pageViews | where timestamp {TimeRange} | where url contains "/case-detail/" and url contains "/notes" | summarize dcount(user_Id));
print
    ['Case Detail Users'] = CaseDetailUsers,
    ['Users Visiting Case Notes Tab'] = NotesUsers,
    ['Case Notes Visit Rate %'] = round(iif(CaseDetailUsers > 0, 100.0 * NotesUsers / CaseDetailUsers, 0.0), 1)
